<script setup lang="ts">
import {useSessionStore} from '../stores/session';
import {ref,watch,onMounted,onUnmounted} from 'vue';
import {useBusinessStore,businessApi} from '../stores/business';
import type {NativeTaskList,NativeTaskDetail,NativeContext,BusinessResult,NativeIncident} from '@shared/business';
import BusinessPlanCard from './BusinessPlanCard.vue';
import NativeIncidentCard from './business/NativeIncidentCard.vue';
const business=useBusinessStore(),open=ref(false),busy=ref(false),error=ref(''),data=ref<NativeTaskList>(),selected=ref<BusinessResult>(),selectedCard=ref(''),incidentId=ref(''),incidentTask=ref(''),showIncident=ref(false),incidents=ref<NativeIncident[]>([]);
const session=useSessionStore();
const labels:Record<string,string>={'schedule.move':'调课','duty.handover':'检查交接','duty.accept':'接收交接','duty.reassign':'指定接收人','duty.item':'遗留事项','resource.patch':'资源数据修正','issue.create':'报修','issue.action':'工单处理','notification.publish':'通知','closure.create':'停用','closure.revoke':'恢复开放','incident.bundle':'故障联合办理','incident.restore':'故障恢复','incident.takeover':'事件接续'};
const statuses:Record<string,string>={draft:'草稿 / 待准备',awaiting_confirmation:'待本人确认',executed:'已提交 · 可回查',stale:'依据变化 · 可重算',expired:'方案过期 · 可重算',resolved:'事件已完成 · 可回查',in_progress:'事件办理中 · 可回查',delegated:'由其他管理员接续',rejected:'已拒绝',permission_changed:'权限变化 · 暂不可办理'};
async function work(fn:(scope:string)=>Promise<void>){busy.value=true;error.value='';const scope=business.scopeKey;try{await fn(scope);}catch(e){error.value=(e as Error).message;}finally{busy.value=false;}}
function valid(scope:string){return business.connected&&business.scopeKey===scope;}
async function refresh(){await work(async scope=>{const d=await businessApi<NativeTaskList>('proxy/tasks');if(!valid(scope))return;data.value=d;if(business.profile?.identity==='admin'){const i=await businessApi<{incidents:NativeIncident[]}>('proxy/incidents');if(valid(scope))incidents.value=i.incidents;}});}
async function show(){open.value=true;await refresh();}
async function resume(id:string){await work(async scope=>{const r=await businessApi<NativeTaskDetail>('proxy/tasks/'+id);if(!valid(scope))return;
 if(r.task.kind.startsWith('incident.')){showIncident.value=true;incidentId.value=r.task.entityId;incidentTask.value=id;selected.value=undefined;return;}
 const ctx=await businessApi<NativeContext>('proxy/context');if(!valid(scope))return;const view=r.task.kind==='resource.patch'?'health':r.task.kind==='schedule.move'?'schedule':r.task.kind.startsWith('duty.')?'duty':r.task.kind.startsWith('issue.')?'issues':r.task.kind.startsWith('closure.')?'closures':'notifications';
 selected.value={summary:'从原系统任务恢复',planId:r.plan?.id||null,plan:r.plan||undefined,receipt:r.receipt||undefined,view,context:ctx,task:r.task,taskId:r.task.id,candidates:r.candidateSet?.kind==='schedule.move'?r.candidateSet.candidates:[],candidateSetId:r.candidateSet?.id,sourceLesson:r.candidateSet?.kind==='schedule.move'?r.candidateSet.source:undefined,date:r.candidateSet?.kind==='schedule.move'?r.candidateSet.date:r.plan?.payload.date,scopeKey:scope,source:'原系统持久任务',queriedAt:data.value?.queriedAt,workbenchUrl:'/operations.html?bridge=1'};selectedCard.value='task:'+r.task.id;showIncident.value=false;
 });}
async function queue(view:'duty'|'issues'|'health'){await work(async scope=>{const ctx=await businessApi<NativeContext>('proxy/context');if(!valid(scope))return;selected.value={summary:'查询当前原账号工作队列',planId:null,view,context:ctx,candidates:[],scopeKey:scope,source:'原系统工作队列',workbenchUrl:'/operations.html?bridge=1'};selectedCard.value='queue:'+view;showIncident.value=false;});}
function newIncident(){showIncident.value=true;incidentId.value='';incidentTask.value='';selected.value=undefined;}
watch(()=>business.scopeKey,()=>{data.value=undefined;selected.value=undefined;incidents.value=[];showIncident.value=false;incidentId.value='';if(open.value&&business.connected)void refresh();});
function target(event:Event){const destination=(event as CustomEvent).detail;if(destination.taskId){open.value=true;void resume(destination.taskId);}else if(destination.roomId){open.value=true;void work(async scope=>{const context=await businessApi<NativeContext>('proxy/context');if(!valid(scope))return;selected.value={summary:'从主系统实验室入口继续办理',view:destination.action||'issues',initialRoomId:destination.roomId,context,planId:null,candidates:[],scopeKey:scope,source:'主系统授权工作台',workbenchUrl:'/operations.html?bridge=1'};selectedCard.value='room:'+destination.roomId+':'+destination.action;});}}
onMounted(()=>window.addEventListener('labops-target',target));onUnmounted(()=>window.removeEventListener('labops-target',target));
</script>
<template><div v-if="business.connected" class="native-work-entry"><button type="button" @click="show" :disabled="busy">我的工作</button><button v-if="business.profile?.identity==='admin'&&session.currentMode()!=='chat'" type="button" @click="open=true;newIncident()">登记故障事件</button><span>按原账号恢复任务、待接收交接与工单</span></div>
 <div v-if="open&&business.connected" class="native-work-mask" @click.self="open=false"><section class="native-work-panel" role="dialog" aria-modal="true" aria-label="我的工作"><header><b>我的工作 · {{business.profile?.username}}</b><button @click="refresh" :disabled="busy">刷新工作队列</button><button aria-label="关闭我的工作" @click="open=false">关闭</button></header><p v-if="error" role="alert">{{error}}</p>
  <div v-if="data" class="native-work-queues"><span>待本人确认 {{data.queues.confirmation.length}}</span><button @click="queue('duty')">待接收交接 {{data.queues.receive.length}}</button><button @click="queue('issues')">待处理工单 {{data.queues.processing.length}} · 待验收 {{data.queues.acceptance.length}}</button><button v-if="business.profile?.identity==='admin'" @click="queue('health')">资源数据健康</button><span>可恢复草稿 {{data.queues.recovery.length}}</span></div>
  <details v-if="data" open><summary>原系统任务 {{data.tasks.length}} 项</summary><div v-for="t in data.tasks" :key="t.id" class="native-work-row"><div><b>{{labels[t.kind]||t.kind}} · {{statuses[t.status]||t.status}}</b><p>{{t.id}} · {{t.entityId||'独立任务'}} · 修订 {{t.revision}} · {{t.updatedAt}}</p></div><button :data-task-id="t.id" :disabled="busy" @click="resume(t.id)">继续 / 回查</button></div><p v-if="!data.tasks.length">尚无原系统任务。可在对话中查询或准备业务方案。</p></details>
  <details v-if="incidents.length"><summary>故障事件 {{incidents.length}} 项</summary><button v-for="i in incidents" :key="i.id" @click="showIncident=true;selected=undefined;incidentId=i.id;incidentTask=(i.coordinatorId||i.actorId)===business.profile?.username?i.taskId:''">{{i.roomName}} · {{i.date}} · {{i.description}} · {{i.id}}</button></details>
  <NativeIncidentCard v-if="showIncident" :key="incidentId||'new'" :scope-key="business.scopeKey" :incident-id="incidentId||undefined" :task-id="incidentTask||undefined" :readonly="session.currentMode()==='chat'"/>
  <BusinessPlanCard v-if="selected" :key="selected.taskId||selectedCard" :result="selected" :card-id="selectedCard" :readonly="session.currentMode()==='chat'"/>
 </section></div>
</template>
<style scoped>
.native-work-entry{display:flex;gap:8px;align-items:center;flex-wrap:wrap;padding:6px 20px;border-bottom:1px solid var(--border);font-size:11px;color:var(--text-muted)}button{font:inherit;border:1px solid var(--border-strong);border-radius:7px;padding:7px 10px;background:var(--surface-2);color:var(--text);cursor:pointer}button:disabled{opacity:.5}.native-work-mask{position:fixed;inset:0;background:#07162399;z-index:50;display:flex;justify-content:center;padding:24px}.native-work-panel{background:var(--surface);color:var(--text);border-radius:14px;padding:20px;width:min(960px,100%);overflow:auto}.native-work-panel header{display:flex;gap:12px;align-items:center;flex-wrap:wrap;position:sticky;top:-20px;padding:10px 0;background:var(--surface);z-index:1}.native-work-panel header b{margin-right:auto}.native-work-queues{display:flex;gap:10px;flex-wrap:wrap;align-items:center;padding:15px 0;font-size:13px}.native-work-row{display:flex;gap:10px;align-items:center;justify-content:space-between;border-bottom:1px solid var(--border);padding:10px 0;font-size:13px}.native-work-row p{font-size:11px;color:var(--text-muted);overflow-wrap:anywhere}.native-work-panel details{margin:12px 0}.native-work-panel .native-card{margin-top:16px}@media(max-width:600px){.native-work-mask{padding:0}.native-work-panel{border-radius:0;padding:12px}.native-work-row{flex-direction:column;align-items:stretch}.native-work-entry span{display:none}}
</style>
